using System;using System.IO;using System.Text;using System.Reflection;using System.Collections.Generic;
public class ConsoleCmdBatchTwoSave:ConsoleCmdAbstract {
 public override string[] getCommands(){return new[]{"batchtwosave"};}
 public override string getDescription(){return "Isolated saved-world audit for batch two.";}
 public override void Execute(List<string> args,CommandSenderInfo sender){try{
  if(args.Count>0 && args[0]=="worker"){var a=Assembly.Load(File.ReadAllBytes(Path.Combine(ModManager.GetMod("BatchTwoSaveTools",true).Path,"Worker.dll")));SdtdConsole.Instance.Output((string)a.GetType("BatchTwoSaveWorker").GetMethod("Run").Invoke(null,new object[]{args.Count>1?args[1]:"audit"}));return;}
  var world=GameManager.Instance.World;if(world.GetPlayers().Count!=0)throw new Exception("Empty isolated save server required");
  var provider=world.ChunkCache.ChunkProvider;var field=typeof(ChunkProviderGenerateWorld).GetField("m_RegionFileManager",BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance);var manager=(RegionFileManager)field.GetValue(provider);
  string folder=ModManager.GetMod("BatchTwoSaveTools",true).Path;var report=new StringBuilder();var keys=manager.GetAllChunkKeys();report.AppendLine("Saved chunks="+keys.Length);
  var chunks=new Dictionary<long,Chunk>();int containers=0;var csv=new StringBuilder("x,z,oldHeight,newHeight,terrainHeight,topCells\n");
  foreach(var key in keys){var c=manager.GetChunkSync(key);if(c==null)throw new Exception("Unreadable chunk "+key);chunks.Add(key,c);report.AppendLine("CHUNK "+c.X+","+c.Z+" entities="+c.entityStubs.Count+" tileEntities="+c.GetTileEntities().Count);foreach(var te in c.GetTileEntities().list){var composite=te as TileEntityComposite;var storage=composite==null?null:composite.GetFeature<TEFeatureStorage>();if(storage!=null){containers++;report.AppendLine("STORAGE "+te.ToWorldPos()+" block="+c.GetBlock(te.localChunkPos).Block.GetBlockName()+" loot="+storage.lootListName+" empty="+storage.IsEmpty());}}}
  int affected=0;using(var reader=new BinaryReader(File.OpenRead(Path.Combine(folder,"columns.bin"))))while(reader.BaseStream.Position<reader.BaseStream.Length){int x=reader.ReadInt32(),z=reader.ReadInt32();float before=reader.ReadUInt16()/257f,after=reader.ReadUInt16()/257f;Chunk chunk=null;foreach(var c in chunks.Values)if(c.X==(x>>4)&&c.Z==(z>>4)){chunk=c;break;}if(chunk==null)continue;affected++;if(affected>120)continue;int lx=x&15,lz=z&15;var cells=new StringBuilder();for(int y=(int)Math.Floor(before)-3;y<=Math.Ceiling(before)+3;y++)cells.Append(y+":"+chunk.GetBlock(lx,y,lz).Block.GetBlockName()+":"+chunk.GetDensity(lx,y,lz)+";");csv.AppendLine(x+","+z+","+before+","+after+","+chunk.GetTerrainHeight(lx,lz)+","+cells);}
  report.AppendLine("Containers="+containers+" affected exterior columns="+affected);File.WriteAllText(Path.Combine(folder,"save-audit.txt"),report.ToString());File.WriteAllText(Path.Combine(folder,"terrain-columns.csv"),csv.ToString());SdtdConsole.Instance.Output("[BatchTwoSave] PASS read-only audit "+keys.Length+" chunks; "+containers+" storage entities; "+affected+" apron columns.");
 }catch(Exception e){SdtdConsole.Instance.Output("[BatchTwoSave] FAIL "+e);}}
}
